"""Create non-observation contract, exact schedule, and deterministic resource model."""
from b2b_common import *
from b2b_schedule import generate,validate_schedule
def main():
    env=read(NOTES/'B2_B_freeze_environment.json');build=read(LOG/'build_manifest.json')
    points=workloads();schedule=generate(points);validate_schedule(schedule,points)
    cores=[r['logical_cpu'] for r in env['linux']['selected_cores']]
    assert len(cores)==4 and all(p['L']==1 for p in points)
    win=env['windows'];assert win['processor']['NumberOfCores']==8 and win['processor']['NumberOfLogicalProcessors']==16 and 'Ryzen 7 3700X' in win['processor']['Name']
    assert all(k in read(LOG/'parent_evidence_verification.json') for k in ('B2_A_artifact_hashes.json','B1_primary_audit/artifact_hashes.json'))
    write(NOTES/'B2_B_workload_matrix.json',dict(points=points,point_count=12,point_view_cells=24,all_B2B_L_equals_1=True,views=['COLD','ONLINE'],fixture=dict(public_seed=DATA_SEED_LABEL,sha256=DATA_SEED_DIGEST,integer_seed=str(DATA_SEED),integer_seed_hex=hex(DATA_SEED),derivation='First 8 SHA256 bytes interpreted little-endian uint64; SplitMix64 state = seed XOR (N<<32) XOR ell. Words emitted little endian; identical N/ell raw bytes for every alpha; never seeds cryptographic randomness.')))
    write(NOTES/'B2_B_run_schedule.json',schedule)
    counts=dict(points=12,point_view_cells=24,warmup_pairs_per_cell=3,measured_pairs_per_cell=10,pair_slots=312,warmup_pair_slots=72,measured_pair_slots=240,parent_attempts=624,packed_parents=312,repeated_parents=312,warmup_parents=144,measured_parents=480,worker_attempts=1248,warmup_workers=288,measured_workers=960,workers_by_alpha={'2':312,'3':416,'4':520},pair_slots_per_alpha=104)
    memory_evidence=[]
    for p in read(NOTES/'B1_primary_point_results.json'):
        if p['N'] not in (1024,4096):continue
        for view in ('COLD','ONLINE'):
            for method in ('packed','repeated'):
                d=p[view][method]
                memory_evidence.append(dict(point=p['point_id'],view=view,method=method,metric=d['RSS_metric'],maximum_KiB=d['worker_peak_RSS_KiB']['max']))
    model=[]
    for p in points:
        N=p['N'];a=p['alpha'];encoded=N*p['encoded_record_bytes'];imported=N*4096*2*8;query_shoup=2*N*CT;raw=N*p['ell_bits']//8
        margin=512*2**20; transient=16*2**20
        resident=encoded+imported+query_shoup+raw+margin+transient;virtual=resident+512*2**20
        model.append(dict(point_id=p['point_id'],alpha=a,N=N,ell_bits=p['ell_bits'],packed_query_ciphertexts=N,repeated_query_ciphertexts=a*N,packed_reply_ciphertexts=1,repeated_reply_ciphertexts=a,packed_query_bytes=N*CT,repeated_query_bytes=a*N*CT,packed_reply_bytes=CT,repeated_reply_bytes=a*CT,encoded_DB_bytes_per_worker=encoded,imported_RNS_bytes_per_worker=imported,query_plus_Shoups_bytes_per_worker=query_shoup,raw_DB_bytes_per_worker=raw,fixed_resident_margin_bytes=margin,transient_margin_bytes=transient,estimated_resident_per_worker_bytes=resident,estimated_repeated_RSS_upper_bytes=a*resident,estimated_virtual_per_worker_bytes=virtual,estimated_repeated_address_space_bytes=a*virtual,estimate_not_measurement=True,per_worker_cap_feasible=virtual<CAPS['per_worker_address_space_bytes'],aggregate_cap_feasible=a*max(virtual,resident)<CAPS['aggregate_address_space_bytes']))
    feasible=all(p['per_worker_cap_feasible'] and p['aggregate_cap_feasible'] for p in model) and env['linux']['memory_bytes']['MemAvailable']>=CAPS['aggregate_rss_bytes']+CAPS['parent_rss_bytes'] and env['linux']['disk']['free']>=CAPS['disk_free_reserve_bytes']+CAPS['batch_disk_bytes']
    resource=dict(status='FEASIBLE' if feasible else 'BLOCKED',caps=CAPS,model=model,B1_memory_evidence=memory_evidence,B1_memory_source='revision_notes/B1_primary_point_results.json',B1_memory_source_sha256=sha(NOTES/'B1_primary_point_results.json'),B2A_layout_source='revision_notes/B2_A_feasibility_frontier.json',B2A_layout_sha256=sha(NOTES/'B2_A_feasibility_frontier.json'),formal_timing_observations_used=0,cap_equality='Same timeout, per-process RLIMIT_AS, file/disk policy and monitor for both methods; repeated legitimately has alpha private workers. No aggregate-cap division by alpha.',address_space_policy='8 GiB RLIMIT_AS per worker plus sampled 16 GiB aggregate VmSize threshold; 16 GiB aggregate RSS threshold; both measured at 10 ms. Static margins are feasibility estimates, not a guarantee against resource failures.',disk_model=dict(ciphertexts_persisted=False,per_native_output_limit_bytes=2**20,maximum_parent_task_directories=624,task_bound_bytes=8*2**20,whole_batch_task_bound_bytes=624*8*2**20,batch_cap_bytes=16*2**30),host_available_memory_bytes=env['linux']['memory_bytes']['MemAvailable'],host_free_disk_bytes=env['linux']['disk']['free'])
    assert feasible,'Resource preflight blocked'
    write(NOTES/'B2_B_resource_preflight.json',resource)
    concurrency=dict(selected_cores=env['linux']['selected_cores'],selection_rule='Allowed CPUs only; sort (package_id,core_id,logical_cpu); lowest allowed logical representative per core; first four physical cores.',parent_affinity=cores,packed_affinity=[cores[0]],repeated_affinity={str(a):[[c] for c in cores[:a]] for a in (2,3,4)},OMP_NUM_THREADS=1,OMP_DYNAMIC=False,MULTI_THREAD=False,packed_workers=1,repeated_workers='alpha',fixed_total_core_comparison=False,release_clock='CLOCK_MONOTONIC_RAW',release_lead_ns=5_000_000,release_protocol='Independent exec -> private staging -> READY all -> one future raw-clock timestamp -> start; preserve requested/actual start/end/skew. No skew exclusion. Parent on c0..c3; no fifth monitor core.',validation_protocol='All workers signal DONE after task_end; parent releases validation only after all DONE, avoiding validation overlap with timed peers.',server_semantics='Each independent process owns private raw/encoded/imported DB, server, fresh client/key and process-global native Salsa state. Not a shared persistent multi-request server.')
    phases=dict(clock='CLOCK_MONOTONIC_RAW',vocabulary=PHASES,COLD=PHASES[:8],ONLINE=['ConfigureClient','ClientSetupKeyGen','QueryGen','ReplyGen','ReplyExt'],ONLINE_staging=['ConfigureServer','EncodeDB','ImportPreprocess'],ValidationOverhead='Outside TaskTotal and after peer completion barrier. Includes all coefficients, all radix segments, all records, padding and hashes.',raw_fixture='Deterministic raw bytes staged before READY for both views. EncodeDB remains inside COLD TaskTotal.',packed_TaskTotal='packed_task_end - packed_task_start',repeated_TaskTotal='max(worker_end_r) - min(worker_start_r)',TaskTotal='Independent endpoint interval, never phase sum',repeated_phase_summary='Sum of worker phase spans: aggregate phase work, never critical-path phase latency')
    analysis=dict(primary_variable='paired_completed_task_ratio',formula='T_repeated / T_packed for same alpha,N,ell,view,pair_id',interpretation='R>1 packed lower completed-task latency; R=1 equal; R<1 repeated lower latency. No monotonicity requirement.',per_method_statistics=['median','Q1','Q3','IQR','min','max','mean','sample_SD'],quantile='Type 7',bootstrap=dict(seed=BOOTSTRAP_SEED,resamples=10000,method='paired percentile 95% CI for median paired ratios',PRNG='Python random.Random; new independent Random(seed) for every cell; choices(ratios,k=n_complete)',complete_case_size=10,incomplete_case_policy='Use only complete pairs, resampling n_complete pairs; report n_complete/n_incomplete; zero complete => null median/CI. No imputation or replacement.'),outlier_removal=False,pooled_B1_samples=False,prohibited=['grand ratio','all-alpha geometric mean','global speedup','pooled hypothesis test','regression slope','alpha significance test','ANOVA','mixed-effects model'],future_scaling_table='Eight rows (N,ell,view), each with R2,R3,R4 and pointwise CIs; never average the three ratios.')
    failure=dict(statuses=STATUSES,warmup='Any warmup failure => BATCH_ANALYSIS_INVALID; preserve all attempts; no rerun',measured='Retain failure; mark pair incomplete; only complete pairs enter ratios; no imputation/rerun',environment='Known host suspend/reboot, resource failure, swapping/thrashing or observed throttling invalidates whole batch; retain all rows and add incident record',resource_stop='Batch disk/reserve breach stops further native launches; remaining scheduled parents retained as explicit unstarted RESOURCE_LIMIT records',start_skew='Retain; no post-hoc exclusion')
    config=dict(freeze_version='B2B-1.0',purpose='Pre-observation controlled multiplicity scalability freeze',integrity_policy='MANIFEST_LEVEL_V1',research_question='RQ3b: How does the implemented packed retrieval scale with retrieval multiplicity alpha under fixed radix width rho_0=8 and required plaintext capacity w=alpha*rho_0?',domain=dict(alpha=[2,3,4],rho_0=[8],w_by_alpha={'2':16,'3':24,'4':32},N=[1024,4096],ell_bits=[512,2048]),all_B2B_L_equals_1=True,workloads=points,views=['COLD','ONLINE'],target_formula='floor((2r-1)N/(2alpha)), r=1..alpha, zero-based canonical order only',fixture=read(NOTES/'B2_B_workload_matrix.json')['fixture'],backend_commit=COMMIT,crypto=CRYPTO,build=build,host=env,concurrency=concurrency,resource_caps=CAPS,phases=phases,counts=counts,analysis=analysis,failure_rules=failure,same_profile_rule='Packed(alpha,8,8alpha) versus alpha independent single-record XPIR requests using the exact same rho,w,layout,encoding,q,n,Berr,backend,sampler,PRNG,compiler,raw DB,targets and preprocessing semantics. No T0 cross-profile comparator.',fresh_key_rule='Fresh exec/client/key per worker; exactly N direct native encryptions per worker; no extra diagnostic ciphertext; retire after task. Packed uses direct K_r=256^(r-1); repeated uses 1 at its sole target and 0 elsewhere.',alpha2_rule='Freshly remeasure alpha2 with the same B2-B binary, host policy, schedule and analysis. B1 evidence remains separate; never pool sample sizes.',payload=dict(ciphertext_bytes=CT,packed_query_CT='N',packed_reply_CT='L=1',repeated_query_CT='alpha*N',repeated_reply_CT='alpha*L=alpha',measurement='Actual copied native ciphertext buffer counts and bytes; sanity expectations are not measurements',transport_bytes='NOT_MEASURED'),CPU=dict(worker='RUSAGE_SELF user/system delta across TaskTotal',packed='Single worker CPU delta',repeated='Sum of all alpha worker CPU deltas',parent='Parent CPU separately across orchestration/validation; not added to arithmetic CPU',CPU_work_ratio='Repeated aggregate CPU median / packed aggregate CPU median; descriptive resource metric, not latency speedup'),RSS=dict(packed='WORKER_LIFETIME_PEAK_RSS',repeated='SUM_OF_WORKER_PEAK_RSS_UPPER',ONLINE='Staging included in lifetime RSS',parent='Separate lifetime RSS',prohibited_interpretation='Not synchronized total peak; ratio is not directly a memory-saving claim'),schedule=dict(path='revision_notes/B2_B_run_schedule.json',sha256=sha(NOTES/'B2_B_run_schedule.json'),seed=ORDER_SEED,derivation='SHA256(seed + ASCII | + purpose + ASCII | + sorted compact JSON metadata). Warmup rounds 0..2 precede measured rounds 0..9; each has all 24 cells, sorted by round hash. Independently hash-rank repetitions 0..9 per cell; first five packed-first. Warmup hash fixes a 2/1 orientation.',pair_adjacency='Execute the two methods consecutively in frozen order; no other task between; no forced cooldown'),security_boundary=BOUNDARY,secondary_status='RETIRED_FROM_CURRENT_SCOPE',prohibited_actions=['No formal observations during freeze','No B1-secondary execution','No B1/B2-A performance pooling','No manuscript/proof edits','No parameter search or crypto optimization','No L>1 extrapolation','No second fixed-core experiment'],zero_formal_observations=True,next_stage='B2_B_CONTROLLED_SCALABILITY_EXECUTION')
    write(LOG/'freeze_config.json',config)
    table='| alpha | rho_0 | w | N | ell_bits | J | L | target tuple |\n|---:|---:|---:|---:|---:|---:|---:|---|\n'+''.join(f"| {p['alpha']} | 8 | {p['w']} | {p['N']} | {p['ell_bits']} | {p['J']} | 1 | {p['target_tuple']} |\n" for p in points)
    write(NOTES/'B2_B_workload_matrix.md','# B2-B frozen workload matrix\n\n'+table+'\nEach point has COLD and ONLINE views: 24 cells. All L=1; no inference for L>1. Canonical targets only; raw bytes identical across alpha at fixed N/ell. Exact DB hashes and public seed derivation are in the JSON.\n')
    write(NOTES/'B2_B_concurrency_contract.md','# B2-B resource/concurrency contract\n\nThe repeated baseline is allowed one physical core per independent request, whereas the packed implementation remains serial. This is a service-level latency comparison, not fixed total cores. No second fixed-core experiment.\n\n```json\n'+json.dumps(concurrency,indent=2)+'\n```\n\n'+json.dumps(phases,indent=2))
    write(NOTES/'B2_B_resource_preflight.md','# B2-B resource preflight\n\nFEASIBLE under the static model and captured host availability. No new memory benchmark or timing observation was run. The JSON retains exact native buffer counts, B1 measured memory context, B2-A layout provenance and per-point estimates.\n\n```json\n'+json.dumps(CAPS,indent=2)+'\n```\n\nPer worker: raw bytes + encoded bytes + imported two-prime RNS + query and Shoup buffers + 512 MiB resident margin + 16 MiB transient margin. Address-space estimate adds 512 MiB per process. Estimates are feasibility screens, not observed B2-B RSS. Each worker keeps its full 8 GiB RLIMIT_AS; aggregate VmSize and RSS separately have 16 GiB sampled thresholds. A 10 ms monitor can detect a transient only when sampled. No ciphertext buffers are persisted.\n\nB1 memory context is read-only; no B1 timing is incorporated. Formal execution must recheck RAM, disk, topology and power policy.\n')
    write(NOTES/'B2_B_statistics_plan.md','# B2-B frozen statistics plan\n\n```json\n'+json.dumps(analysis,indent=2)+'\n```\n\n'+json.dumps(failure,indent=2)+'\n\nOnly future FORMAL B2-B rows from this release, one batch and the exact schedule may enter analysis. Functional/synthetic rows and all B1 rows are rejected. Unit tests may use hand-constructed numbers; no measured performance result or bootstrap output is generated during freeze. Incomplete-pair bootstrap uses n_complete, without filling missing pairs. Full success uses 10 draws from 10 complete ratios per resample.\n')
    write(NOTES/'B2_B_protocol.md','# B2-B controlled scalability preregistration\n\n'+config['research_question']+'\n\nFixed radix width rho_0=8, with plaintext capacity increasing as required by w=alpha*rho_0. The experiment does not vary alpha while holding every representation parameter constant.\n\nOne comparison unit is one completed ordered alpha-record retrieval task. '+config['same_profile_rule']+'\n\n'+config['alpha2_rule']+'\n\n'+config['fresh_key_rule']+'\n\nThe concurrency, phase, resource, workload and statistics companion artifacts define the complete contract. Three warmup and ten measured pairs per cell; 312 pair slots, 624 parent attempts and 1248 worker attempts. Every measured cell has exactly five packed-first and five repeated-first pairs. All 13 rounds interleave the 24 cells using the frozen public SHA256 schedule.\n\nTaskTotal uses independent CLOCK_MONOTONIC_RAW endpoints. Repeated = max(end)-min(start), never sum or mean worker duration. Aggregate phase work and aggregate CPU are resource descriptors. Validation follows all worker task endpoints. ONLINE private preprocessing is outside TaskTotal but inside lifetime RSS. Actual copied ciphertext bytes are payload, not network traffic; transport is NOT_MEASURED.\n\nMANIFEST_LEVEL_V1: SHA256 for every artifact, centralized path/size/hash/role entries. Only the release manifest and executable receive sidecars in this stage. Existing B2-A sidecars remain untouched. The manifest does not hash itself. No empty post-execution artifact index is created.\n\nFreeze environment is preregistration only. Before the first formal observation, a fresh Windows snapshot and Linux release gate must validate host identity, core topology/availability, power plan, RAM/disk, sources, dependencies, compiler, libraries, executable and release hashes. Future execution uses one immutable B2_B_execution directory with no retries or replacements. No intentional competing compute or unrecorded monitor core. Known suspend, reboot, swapping, resource incident or throttling invalidates the entire batch, never selected samples.\n\nB1-secondary remains RETIRED_FROM_CURRENT_SCOPE. T0 remains independent disjoint tuning/sensitivity evidence, not global optimality. No backend parameter search, cryptographic optimization, shared-memory baseline, manuscript integration or formal-proof edits.\n\n'+BOUNDARY+'\n\nThis stage compiles, validates and seals only. At most one tiny N=8, ell=256 packed functional smoke per alpha exercises the changed harness; no TaskTotal/phase/CPU/RSS fields are emitted. No formal workload may be used as smoke.\n\nNext stage: B2_B_CONTROLLED_SCALABILITY_EXECUTION. Execution is not authorized by this freeze artifact and must await the next user instruction.\n')
    write(NOTES/'B2_B_open_issues.md','# B2-B freeze open issues and limits\n\n1. WSL2 host-managed frequency/turbo remains unexposed; this is not bare metal. Freeze snapshot is not future release approval.\n2. Repeated uses alpha physical cores and alpha private DB/server instances; Packed uses one. This is not equal active arithmetic cores or a shared persistent multi-request server.\n3. All workloads have L=1; larger reply-block behavior is outside scope.\n4. B2-A API-limited rho12/rho16 frontier cells remain unchanged and are outside this rho8 domain.\n5. Nonmonotone, flat or increasing pointwise ratios are all valid outcomes. No global alpha summary or significance test.\n6. '+BOUNDARY+'\n7. Resource feasibility is a static margin-based screen. Future resource failures remain failures; no post-observation cap change or rerun.\n8. Only three tiny packed encrypted smoke cases are permitted. Repeated process/barrier semantics receive non-cryptographic tests; no extra encrypted repeated smoke is added.\n9. Existing Windows sandbox denied CIM and default PowerShell policy denied the first script invocation. The read-only snapshot was then captured with approved elevated access and process-local script execution; power settings were never changed. The incomplete first snapshot is retained as diagnostic provenance.\n10. Formal execution still requires fresh release-check and explicit next-stage instruction. No post-execution evidence index exists yet.\n')
    print(json.dumps(dict(prepared=True,counts=counts,resource='FEASIBLE',schedule_sha256=sha(NOTES/'B2_B_run_schedule.json'))))
if __name__=='__main__':main()
